            tagline = "A quiet library room finds a new purpose when readers help shape its future.",
            parts = listOf(
                StoryPart(1, "The Quiet Room", listOf("The library had a small room that was rarely used. It held a few chairs, a table, and a clock that had stopped at twenty past four.", "When the librarian asked the student volunteers how the room could be useful, Imani suggested a place for quiet study and patient conversation about books.", "They agreed to ask readers what they needed before changing anything.")),
                StoryPart(2, "Listening to Readers", listOf("The volunteers placed a suggestion box near the entrance and invited readers to share ideas without writing personal details.", "Some wanted a silent study space; others hoped for a weekly reading circle. The team realised the room could support both if its schedule was clear.", "They drafted a timetable and asked the librarian to review it.")),
                StoryPart(3, "The Stopped Clock", listOf("A caretaker checked the old clock and explained that it was no longer reliable enough to repair. The team decided to keep it as a display item rather than pretend it worked.", "A local craft teacher offered to help make a simple wall display showing the room's new schedule.", "Imani wrote a short note explaining why the clock remained on the shelf: it marked the room's history, not its current time.")),
                StoryPart(4, "A First Reading Circle", listOf("The first reading circle attracted six students. Each person brought a short book recommendation and explained what made it interesting.", "One visitor felt nervous about speaking, so the group allowed people to write recommendations as well as share them aloud.", "The librarian thanked everyone and asked what would make the next session more welcoming.")),
                StoryPart(5, "A Difficult Schedule", listOf("The study group and reading circle both wanted the same afternoon. The volunteers compared attendance patterns and asked the librarian to help find a fair arrangement.", "They moved the reading circle to a different day and kept one open session for quiet study.", "The solution was not perfect for everyone, but the schedule was clear and could be reviewed after a month.")),
                StoryPart(6, "The New Shelf", listOf("Readers donated a small number of books for the room. The librarian checked each one before adding it to the shelf and recorded where it belonged.", "The students made simple subject labels and left enough space for large-print titles.", "Imani noticed that a tidy shelf made it easier for visitors to find a book without asking for help.")),
                StoryPart(7, "A Rainy Afternoon", listOf("Heavy rain kept many visitors indoors, and the quiet room became busier than expected. The volunteers placed a sign outside explaining the room's capacity and the alternative study area.", "When the room reached its safe limit, the librarian directed new arrivals to available tables elsewhere in the building.", "The students learned that a welcoming space also needs sensible limits.")),
                StoryPart(8, "A Note of Thanks", listOf("A reader left a note saying that the room had helped them feel comfortable returning to the library after a long break.", "The volunteers shared the message with the librarian, who asked permission before displaying an anonymous version on the noticeboard.", "The team added a small feedback card to the room so visitors could suggest improvements at any time.")),
                StoryPart(9, "The Room's First Review", listOf("After a month, the librarian and students reviewed the timetable, feedback, and book list. They discovered that the quiet study sessions were well attended, while the reading circle needed a clearer theme.", "The next circle would focus on short mysteries and allow readers to pass if they preferred to listen.", "The volunteers updated the schedule and thanked everyone who had offered thoughtful feedback.")),
                StoryPart(10, "Time for Another Chapter", listOf("The stopped clock remained on the shelf, now beside a card explaining the room's history. The new timetable hung nearby, full of sessions chosen by readers.", "Imani opened the room for the next reading circle and saw familiar faces helping new visitors find seats.", "The room had not become grand or expensive. It had become useful because the people who used it had helped shape it."))
